import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { type STORY_FLAG } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import type { TiledDiggableStructureObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { DiggableComponent } from "../../components/diggable-component";
import { HPComponent } from "../../components/hp-component";
import { InvulnerableComponent } from "../../components/invulnerable-component";

export class DiggableStructure
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #structureTexture: string;
  #storyFlag?: string;
  #hpComponent: HPComponent;
  #invulnerableComponent: InvulnerableComponent;
  #maxHp = 3;
  #invulnerabilityDuration = 500; // milliseconds

  constructor(scene: Phaser.Scene, config: TiledDiggableStructureObject) {
    // Use WESTERN_ASSETS atlas
    const assetKey = ASSET_KEYS.WESTERN_ASSETS;
    const frameName = `${config.texture.toLowerCase()}.png`;

    super(scene, config.x, config.y, assetKey, frameName);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    this.#structureTexture = config.texture;
    this.#storyFlag = config.storyFlag;

    // Add diggable component
    new DiggableComponent(this);

    // Add HP component
    this.#hpComponent = new HPComponent(this, this.#maxHp, this.#maxHp);

    // Add invulnerable component
    this.#invulnerableComponent = new InvulnerableComponent(
      this,
      false,
      this.#invulnerabilityDuration,
    );

    // Set body size to match sprite
    const body = this.body as Phaser.Physics.Arcade.Body;
    body.setSize(config.width, config.height);
    body.setOffset(0, 0);
  }

  enableObject(): void {
    if (this.#hpComponent.HP <= 0) {
      return;
    }
    this.setActive(true);
    this.setVisible(true);
  }

  disableObject(): void {
    this.setActive(false);
    this.setVisible(false);
  }

  get structureTexture(): string {
    return this.#structureTexture;
  }

  /**
   * Called when structure is hit with a tool
   * Returns true if the structure was destroyed
   */
  takeDamage(damage = 1): boolean {
    // Check if already destroyed or invulnerable
    if (this.#hpComponent.HP <= 0 || this.#invulnerableComponent.invulnerable) {
      return false;
    }

    this.#hpComponent.takeDamage(damage);

    // Update visual based on HP
    const hpRatio = this.#hpComponent.HP / this.#maxHp;
    this.setAlpha(hpRatio);

    // Set invulnerable for a short time to prevent multiple hits
    this.#invulnerableComponent.invulnerable = true;
    this.scene.time.delayedCall(this.#invulnerabilityDuration, () => {
      this.#invulnerableComponent.invulnerable = false;
    });

    // If HP reaches 0, destroy the structure
    if (this.#hpComponent.HP <= 0) {
      this.disableObject();
      if (this.#storyFlag) {
        const flag = this.#storyFlag as keyof typeof STORY_FLAG;
        const dataManager = getSceneDataManager(this.scene);
        dataManager.setFlagToCompleted(flag);
      }
      return true;
    }
    return false;
  }

  get hp(): number {
    return this.#hpComponent.HP;
  }

  get invulnerable(): boolean {
    return this.#invulnerableComponent.invulnerable;
  }

  get storyFlag(): string | undefined {
    return this.#storyFlag;
  }
}
