import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadOldBarkTownScenes } from "../gameworld/scene-loaders/old_bark_town";
import OldBarkTownBody from "./OldBarkTownBody";
import { type OldBarkTownState } from "./types";

const OldBarkTownManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: OldBarkTownState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="old_bark_town"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadOldBarkTownScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <>
              <OldBarkTownBody
                state={state}
                teamState={teamState}
                gameNode={gameNode}
              />
            </>
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("old_bark_town-root");
if (elem) {
  const { initialOldBarkTownState: state, initialTeamState } =
    window as unknown as {
      initialOldBarkTownState: OldBarkTownState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <OldBarkTownManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount OldBarkTownManager because #old_bark_town-root was nowhere to be found",
  );
}
