import { newClient } from "@hunt/public-client";
import * as Phaser from "phaser";
import apiUrl from "../../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../../utils/staticSite";
import { ASSET_KEYS, COLOR_CLUE_FRAME_KEYS } from "../../common/assets";
import * as CONFIG from "../../common/config";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import {
  DYNAMIC_INJECTION_TYPE,
  REVEAL_TRIGGER,
} from "../../common/tiled/constants";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { type CharacterColor, type CustomObject } from "../../common/types";
import { DiggableComponent } from "../../components/diggable-component";
import { VisibilityComponent } from "../../components/visibility-component";
import { appendGameworldActivityEntry } from "../../gameworldLocalState";
import { Mine } from "../mons/mine";
import { ColorClue } from "../objects/color-clue";

export const MINESWEEPER_BOARD_COUNT = 10;
const ALL_CHARACTER_COLORS: CharacterColor[] = [
  "GREEN",
  "BLUE",
  "RED",
  "YELLOW",
];

type ColorClueFrameKey =
  (typeof COLOR_CLUE_FRAME_KEYS)[keyof typeof COLOR_CLUE_FRAME_KEYS];

// Helper function to process the grid
export function processGrid(grid: number[][]): {
  grid: number[][];
  numClues: number;
} {
  const rows = grid.length;
  const cols = grid[0]?.length || 0;
  const processedGrid: number[][] = [];
  let numClues = 0;

  for (let row = 0; row < rows; row++) {
    processedGrid[row] = [];
    for (let col = 0; col < cols; col++) {
      if (grid[row][col] === 1) {
        // This is a mine
        processedGrid[row][col] = -1;
      } else {
        // Count surrounding mines
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            const nr = row + dr;
            const nc = col + dc;
            if (
              nr >= 0 &&
              nr < rows &&
              nc >= 0 &&
              nc < cols &&
              grid[nr][nc] === 1
            ) {
              count++;
            }
          }
        }
        if (count !== 0) {
          numClues++;
        }
        processedGrid[row][col] = count;
      }
    }
  }

  return { grid: processedGrid, numClues: numClues };
}

export type MinesweeperInjectionType =
  | "MINESWEEPER_STANDARD"
  | "MINESWEEPER_BILLIARDS"
  | "MINESWEEPER_POKEMON";

// Minesweeper life cycle:
// In game-scene we call the minesweeper constructor to have a placeholder object.
// When applying the gameworld state we call updateStateFromGameworld to load the specific board.
// TODO: When we get an explosion websocket event set explosionCount and load the specific board.
// TODO: When we get a complete websocket event set completed and call revealGrid.
export class Minesweeper
  extends Phaser.GameObjects.Container
  implements CustomObject
{
  #id: number;
  #databaseId: string;
  #injectionType: MinesweeperInjectionType;
  #offset: number;
  #grid: (Mine | ColorClue | null)[][];
  #tileSize = 16; // Using 16x16 tiles to match the map tile size
  #revealedCells = new Set<string>(); // Track which cells have been revealed
  #flaggedCells = new Map<string, Phaser.GameObjects.Sprite>();
  #dugSprites: Phaser.GameObjects.Sprite[] = []; // Track dug sprites for reset
  #highlightSprite?: Phaser.GameObjects.Sprite; // Highlight for tile about to be dug
  #numClues = 0;
  #remainingClues = 0;
  #explosionCount = 0;
  #currentBoard = -1;
  #debugText?: Phaser.GameObjects.Text;
  public completed = false;

  constructor(scene: Phaser.Scene, tiledObject: TiledDynamicInjectionObject) {
    super(scene, tiledObject.x, tiledObject.y);
    this.#id = tiledObject.id;
    this.#explosionCount = 0;
    this.#injectionType = tiledObject.injectionType as MinesweeperInjectionType;
    this.#offset = tiledObject.offset;
    this.#databaseId = `minesweeper_${this.#id}`;

    // Add to scene
    scene.add.existing(this);

    // Render board number on top of the minesweeper in debug mode
    if (CONFIG.ENABLE_DEBUG) {
      this.#debugText = scene.add.text(0, -8, "", {
        fontSize: "10px",
        color: "#ffff00",
        backgroundColor: "rgba(0, 0, 0, 0.6)",
        padding: { x: 4, y: 2 },
      });
      this.#debugText.setOrigin(0.5, 1);
      this.add(this.#debugText);
    }

    // Initialize with empty grid - will be loaded when state is applied
    this.#grid = [];
    this.#numClues = 0;
    this.#remainingClues = 0;

    // Set up physics body for collision detection (will be resized when board loads)
    this.body = scene.physics.add.existing(this)
      .body as Phaser.Physics.Arcade.Body;

    if (!this.body) {
      console.warn("Minesweeper body not found after physics.add.existing");
    }
    this.disableObject();
  }

  // Load a specific board
  #loadBoard(boardNumber: number): void {
    try {
      // Determine asset key based on injection type
      let assetKey: keyof typeof ASSET_KEYS;

      if (
        this.#injectionType === DYNAMIC_INJECTION_TYPE.MINESWEEPER_BILLIARDS
      ) {
        assetKey =
          `MINESWEEPER_BILLIARDS_${boardNumber}` as keyof typeof ASSET_KEYS;
      } else if (
        this.#injectionType === DYNAMIC_INJECTION_TYPE.MINESWEEPER_POKEMON
      ) {
        assetKey =
          `MINESWEEPER_POKEMON_${boardNumber}` as keyof typeof ASSET_KEYS;
      } else {
        assetKey =
          `MINESWEEPER_STANDARD_${boardNumber}` as keyof typeof ASSET_KEYS;
      }

      const gridData = this.scene.cache.json.get(ASSET_KEYS[assetKey]) as {
        mines: number[][];
      };

      if (!gridData) {
        console.error(`Board data not found for ${assetKey}`);
        return;
      }

      const { grid: processedGrid, numClues } = processGrid(gridData.mines);

      // Initialize grid with null values
      this.#grid = processedGrid.map((row) => row.map(() => null));
      this.#numClues = numClues;
      this.#remainingClues = this.#numClues;
      const rows = processedGrid.length;
      const cols = processedGrid[0]?.length || 0;

      // Update physics body size based on grid dimensions
      if (this.body) {
        (this.body as Phaser.Physics.Arcade.Body).setSize(
          cols * this.#tileSize,
          rows * this.#tileSize,
        );
      }

      this.#updateDebugLabel(cols);

      // Create mine enemies and color clue objects based on the grid
      this.#createGridObjects(processedGrid);
    } catch (error) {
      console.error("Error loading minesweeper board:", error);
    }
  }

  // Create mine enemies and color clue objects based on the grid
  #createGridObjects(processedGrid: number[][]): void {
    const rows = processedGrid.length;
    const cols = processedGrid[0]?.length || 0;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const x = col * this.#tileSize;
        const y = row * this.#tileSize;
        const cellValue = processedGrid[row][col];

        if (cellValue === -1) {
          // Create a mine enemy - visible to all colors
          const mine = new Mine({
            scene: this.scene,
            position: { x: x, y: y },
            revealEnemyTrigger: REVEAL_TRIGGER.DIG,
            type: this.#injectionType,
            visibleTo: ["GREEN", "BLUE", "RED", "YELLOW"], // Visible to all colors
          });
          this.#grid[row][col] = mine;
          this.add(mine);
        } else {
          // Create a color clue object that is always visible
          const colorClue = new ColorClue(this.scene, {
            x: x,
            y: y,
            width: this.#tileSize,
            height: this.#tileSize,
            number: cellValue,
            visibleTo: ALL_CHARACTER_COLORS,
            revealClueTrigger:
              cellValue === 0 ? REVEAL_TRIGGER.NONE : REVEAL_TRIGGER.DIG,
            minesweeperInjectionType: this.#injectionType,
          });
          this.#grid[row][col] = colorClue;
          this.add(colorClue);
        }
      }
    }
  }

  // Dig at world coordinates (called by hoe tool)
  public dig(worldX: number, worldY: number): boolean {
    const gridSpace = this.findGridSpace(worldX, worldY);
    if (gridSpace) {
      return this.digAtGridSpace(gridSpace.row, gridSpace.col);
    }
    return false;
  }

  // Toggle a flag at world coordinates (called by flag input)
  public toggleFlag(worldX: number, worldY: number): void {
    if (this.completed) {
      return;
    }

    const gridSpace = this.findGridSpace(worldX, worldY);
    if (!gridSpace) {
      return;
    }

    const cellKey = `${gridSpace.row},${gridSpace.col}`;

    if (this.#revealedCells.has(cellKey)) {
      return;
    }

    const existingFlag = this.#flaggedCells.get(cellKey);
    if (existingFlag) {
      existingFlag.destroy();
      this.#flaggedCells.delete(cellKey);
      return;
    }

    const x = gridSpace.col * this.#tileSize;
    const y = gridSpace.row * this.#tileSize;
    const flagSprite = this.scene.add.sprite(
      x + this.#tileSize / 2,
      y + this.#tileSize / 2,
      ASSET_KEYS.COLOR_CLUES,
      COLOR_CLUE_FRAME_KEYS.FLAG,
    );
    this.add(flagSprite);
    this.bringToTop(flagSprite);
    this.#flaggedCells.set(cellKey, flagSprite);
  }

  // Show highlight for tile that would be dug or flagged
  public showHighlight(
    worldX: number,
    worldY: number,
    frameKey: ColorClueFrameKey = COLOR_CLUE_FRAME_KEYS.DUG,
  ): void {
    const gridSpace = this.findGridSpace(worldX, worldY);
    if (!gridSpace) {
      this.hideHighlight();
      return;
    }

    const x = gridSpace.col * this.#tileSize;
    const y = gridSpace.row * this.#tileSize;

    if (!this.#highlightSprite) {
      this.#highlightSprite = this.scene.add.sprite(
        x + this.#tileSize / 2,
        y + this.#tileSize / 2,
        ASSET_KEYS.COLOR_CLUES,
        frameKey,
      );
      this.#highlightSprite.setAlpha(0.5); // Semi-transparent
      this.add(this.#highlightSprite);
      this.sendToBack(this.#highlightSprite);
    } else {
      this.#highlightSprite.setPosition(
        x + this.#tileSize / 2,
        y + this.#tileSize / 2,
      );
      this.#highlightSprite.setFrame(frameKey);
      this.#highlightSprite.setVisible(true);
    }
  }

  // Hide the highlight
  public hideHighlight(): void {
    if (this.#highlightSprite) {
      this.#highlightSprite.setVisible(false);
    }
  }

  // Find which grid space to dig based on world coordinates
  public findGridSpace(
    worldX: number,
    worldY: number,
  ): { row: number; col: number } | null {
    const relativeX = worldX - this.x;
    const relativeY = worldY - this.y;

    const col = Math.floor(relativeX / this.#tileSize);
    const row = Math.floor(relativeY / this.#tileSize);

    // Check bounds
    if (
      row >= 0 &&
      row < this.#grid.length &&
      col >= 0 &&
      col < this.#grid[0]?.length
    ) {
      return { row, col };
    }

    return null;
  }

  // Dig at a specific grid space
  public digAtGridSpace(row: number, col: number): boolean {
    const cellKey = `${row},${col}`;

    // Check if already revealed
    if (this.#revealedCells.has(cellKey)) {
      return false;
    }

    // Play shovel sound for valid digs (minesweeper isn't covered by the shovel tool's own SFX)
    this.scene.sound.play(ASSET_KEYS.DIG_SFX);

    const existingFlag = this.#flaggedCells.get(cellKey);
    if (existingFlag) {
      existingFlag.destroy();
      this.#flaggedCells.delete(cellKey);
    }

    // Mark as revealed
    this.#revealedCells.add(cellKey);

    // Add dug texture to the dug location
    const x = col * this.#tileSize;
    const y = row * this.#tileSize;
    const dugSprite = this.scene.add.sprite(
      x + this.#tileSize / 2,
      y + this.#tileSize / 2,
      ASSET_KEYS.COLOR_CLUES,
      COLOR_CLUE_FRAME_KEYS.DUG,
    );
    this.add(dugSprite);
    this.#dugSprites.push(dugSprite);
    this.sendToBack(dugSprite);

    const cellObject = this.#grid[row][col];
    if (cellObject) {
      // Check if the object has a diggable component
      const diggableComponent =
        DiggableComponent.getComponent<DiggableComponent>(cellObject);
      if (diggableComponent) {
        diggableComponent.unbury();
      }
      if (cellObject instanceof Mine) {
        // Mine hit! Reset the board for all team members
        this.#handleMineHit();
        return true;
      }
      if (cellObject instanceof ColorClue) {
        if (cellObject.getNumber() > 0) {
          this.#remainingClues--;
        }
      }
      if (CONFIG.MINESWEEPER_INSTANT_COMPLETE || this.#remainingClues === 0) {
        this.#complete();
      }
    }
    return false;
  }

  public enableObject(): void {
    this.setActive(true);
    this.setVisible(true);
    // Enable all objects in the grid
    for (const row of this.#grid) {
      for (const cellObject of row) {
        if (cellObject) {
          cellObject.enableObject();
        }
      }
    }
    // Enable flag sprites that were placed on the grid
    for (const flagSprite of this.#flaggedCells.values()) {
      flagSprite.setActive(true);
      flagSprite.setVisible(true);
    }
  }

  public disableObject(): void {
    this.setActive(false);
    this.setVisible(false);
    // Disable all objects in the grid
    for (const row of this.#grid) {
      for (const cellObject of row) {
        if (cellObject) {
          cellObject.disableObject();
        }
      }
    }
    // Hide any flags while the object is disabled
    for (const flagSprite of this.#flaggedCells.values()) {
      flagSprite.setActive(false);
      flagSprite.setVisible(false);
    }
  }

  public resetObject(): void {
    this.#reset();
    this.#loadBoard(this.#currentBoard);
    this.enableObject();
  }

  #reset(force = false): void {
    if (this.completed && !force) {
      return;
    }
    if (force) {
      this.completed = false;
    }

    // Clear the revealed cells set
    this.#revealedCells.clear();

    // Remove all flag sprites
    this.#flaggedCells.forEach((flagSprite) => {
      flagSprite.destroy();
    });
    this.#flaggedCells.clear();

    // Remove all dug sprites
    this.#dugSprites.forEach((dugSprite) => {
      dugSprite.destroy();
    });
    this.#dugSprites = [];

    this.hideHighlight();

    // Clear all existing grid objects (both mines and color clues)
    for (const row of this.#grid) {
      for (const cellObject of row) {
        if (cellObject) {
          cellObject.destroy();
        }
      }
    }
  }

  #complete(): void {
    this.#revealGrid();

    if (this.completed) {
      return;
    }
    this.completed = true;

    // Update DataManager with minesweeper completion
    const level = getSceneDataManager(this.scene).data.currentArea.level;
    EVENT_BUS.emit(CUSTOM_EVENTS.MINESWEEPER_COMPLETION_TRIGGERED, {
      level,
      minesweeperId: this.#databaseId,
      boardNumber: this.#currentBoard,
    });
    const minesweeperId = this.#id; // Use the numeric ID for DataManager
    getSceneDataManager(this.scene).completeMinesweeper(minesweeperId);

    if (IS_STATIC_SITE) {
      appendGameworldActivityEntry({
        type: "minesweeper_completed",
        level,
        object_id: this.#databaseId,
        frame: null,
      });
    } else {
      // Update database (fire and forget)
      void (async () => {
        try {
          const client = newClient(apiUrl());
          await client.minesweeperCompleted({
            params: { level, minesweeperId: this.#databaseId },
            body: {},
          });
        } catch (error) {
          console.error(
            "Failed to update minesweeper completion in database:",
            error,
          );
        }
      })();
    }
  }

  #revealGrid(): void {
    this.#flaggedCells.forEach((flagSprite) => {
      flagSprite.destroy();
    });
    this.#flaggedCells.clear();

    this.#grid.forEach((row, rowIndex) => {
      row.forEach((cellObject, colIndex) => {
        if (cellObject) {
          // If the cell object is a mine, replace it with a color clue.
          if (cellObject instanceof Mine) {
            const colorClue = new ColorClue(this.scene, {
              x: cellObject.x,
              y: cellObject.y,
              width: this.#tileSize,
              height: this.#tileSize,
              number: 100,
              visibleTo: ["GREEN", "BLUE", "RED", "YELLOW"],
              revealClueTrigger: REVEAL_TRIGGER.NONE,
              minesweeperInjectionType: this.#injectionType,
            });
            this.add(colorClue);
            colorClue.enableObject(); // Enable must be called since the object constructor disables it.
            this.remove(cellObject);
            this.#grid[rowIndex][colIndex] = colorClue;
            // If the cell object is a color clue, unbury it andmake it visible to all colors.
          } else {
            const diggableComponent =
              DiggableComponent.getComponent<DiggableComponent>(cellObject);
            if (diggableComponent?.isBuried()) {
              diggableComponent.unbury();
            }
            const visibilityComponent =
              VisibilityComponent.getComponent<VisibilityComponent>(cellObject);
            if (visibilityComponent) {
              visibilityComponent.setVisibleTo(
                ["GREEN", "BLUE", "RED", "YELLOW"],
                false,
              );
            }
          }
        }
      });
    });
  }

  // Handle mine hit - send update to database.
  #handleMineHit(): void {
    const dataManager = getSceneDataManager(this.scene);
    // Play mine explosion sfx when a dug cell reveals a mine
    this.scene.sound.play(ASSET_KEYS.MINE_EXPLODE_SFX);
    EVENT_BUS.emit(CUSTOM_EVENTS.MINESWEEPER_EXPLOSION_TRIGGERED, {
      level: dataManager.data.currentArea.level,
      minesweeperId: this.#databaseId,
      boardNumber: this.#currentBoard,
    });
    if (IS_STATIC_SITE) {
      appendGameworldActivityEntry({
        type: "minesweeper_explosion",
        level: dataManager.data.currentArea.level,
        object_id: this.#databaseId,
        frame: null,
      });
    } else {
      void (async () => {
        try {
          const client = newClient(apiUrl());
          const level = dataManager.data.currentArea.level;
          await client.minesweeperExplosion({
            params: { level, minesweeperId: this.#databaseId },
            body: {},
          });
        } catch (error) {
          console.error(
            "Failed to update minesweeper explosion in database:",
            error,
          );
        }
      })();
    }

    this.#advanceBoardAfterExplosion();
  }

  public get databaseId(): string {
    return this.#databaseId;
  }

  public initializeBoard(): void {
    if (this.#currentBoard >= 0) {
      return;
    }
    // Start on a random board so each run feels fresh
    const randomExplosions = Math.floor(
      Math.random() * MINESWEEPER_BOARD_COUNT,
    );
    this.#applyState({
      completed: this.completed,
      explosion_count: randomExplosions,
    });
  }

  public updateStateFromGameworld(state: {
    completed: boolean;
    explosion_count: number;
  }): void {
    this.#applyState(state);
  }

  #updateDebugLabel(cols: number): void {
    if (!CONFIG.ENABLE_DEBUG || !this.#debugText) {
      return;
    }
    const displayNumber =
      this.#currentBoard >= 0 ? `Board ${this.#currentBoard + 1}` : "Board ?";
    this.#debugText.setText(displayNumber);
    this.#debugText.setPosition((cols * this.#tileSize) / 2, -4);
  }

  public get currentBoard(): number {
    return this.#currentBoard;
  }

  #applyState(state: { completed: boolean; explosion_count: number }): void {
    this.#explosionCount = state.explosion_count;
    // Calculate current board from explosion count with offset: (explosion_count + offset) % MINESWEEPER_BOARD_COUNT
    this.#reset(true);
    this.#currentBoard =
      (this.#explosionCount + this.#offset) % MINESWEEPER_BOARD_COUNT;
    this.#loadBoard(this.#currentBoard);
    this.completed = state.completed;
    if (state.completed) {
      this.#revealGrid();
    }
  }

  #advanceBoardAfterExplosion(): void {
    this.#applyState({
      completed: false,
      explosion_count: this.#explosionCount + 1,
    });
  }
}
