import { GameOverScene } from "../scenes/game-over-scene";
import { OldBarkTownGameScene } from "../scenes/old_bark_town-game-scene";
import { OldBarkTownPreloadScene } from "../scenes/old_bark_town-preload-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadOldBarkTownScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.OLD_BARK_TOWN_PRELOAD_SCENE,
    OldBarkTownPreloadScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.OLD_BARK_TOWN_GAME_SCENE,
    OldBarkTownGameScene,
    false,
  );
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.start(SCENE_KEYS.OLD_BARK_TOWN_PRELOAD_SCENE);
};
