import type * as Phaser from "phaser";
import { ASSET_KEYS, COLOR_CLUE_FRAME_KEYS } from "../common/assets";
import { DEATH_REASON, DIRECTION, STORY_FLAG } from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import {
  DYNAMIC_INJECTION_TYPE,
  TILED_LAYER_NAMES,
  VEHICLE_TEXTURE,
} from "../common/tiled/constants";
import {
  getAllLayerNamesWithPrefix,
  getTiledDiggableStructureObjectsFromMap,
  getTiledDynamicInjectionObjectsFromMap,
  getTiledVehicleObjectsFromMap,
} from "../common/tiled/utils";
import { type InteractiveGameObject } from "../common/types";
import { Minesweeper } from "../entities/dynamic-injections/minesweeper";
import type { AnimatedObject } from "../entities/objects/animated-object";
import { DiggableStructure } from "../entities/objects/diggable-structure";
import { Train } from "../entities/objects/train";
import { Shovel } from "../entities/tools/shovel";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

export class OldBarkTownGameScene extends BaseGameScene {
  private currentHighlightedMinesweeper?: Minesweeper;
  private minesweepersByRoom = new Map<number, Minesweeper[]>();
  private trainsByRoom = new Map<number, Train[]>();
  private diggableStructuresByRoom = new Map<number, DiggableStructure[]>();

  constructor() {
    super(SCENE_KEYS.OLD_BARK_TOWN_GAME_SCENE);
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      return;
    }

    this.minesweepersByRoom.clear();
    this.trainsByRoom.clear();
    this.diggableStructuresByRoom.clear();

    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => ({
        name: layerName,
        roomId: parseInt(layerName.split("/")[1], 10),
      }),
    );

    const dynamicLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.DYNAMIC_INJECTIONS}`),
    );

    dynamicLayers.forEach((layer) => {
      const objects = getTiledDynamicInjectionObjectsFromMap(map, layer.name);
      objects.forEach((object) => {
        if (
          object.injectionType ===
            DYNAMIC_INJECTION_TYPE.MINESWEEPER_BILLIARDS ||
          object.injectionType === DYNAMIC_INJECTION_TYPE.MINESWEEPER_POKEMON ||
          object.injectionType === DYNAMIC_INJECTION_TYPE.MINESWEEPER_STANDARD
        ) {
          const minesweeper = new Minesweeper(this, object);
          this.getMinesweepersForRoom(layer.roomId).push(minesweeper);
          this.diggableGroup.add(minesweeper);
        }
      });
    });

    // Process vehicles
    const vehicleLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.VEHICLES}`),
    );

    vehicleLayers.forEach((layer) => {
      const objects = getTiledVehicleObjectsFromMap(map, layer.name);
      objects.forEach((object) => {
        // Only create trains for now
        if (object.texture === VEHICLE_TEXTURE.WESTERN_TRAIN) {
          if (
            object.targetDoorId === undefined ||
            object.targetRoomId === undefined
          ) {
            console.warn(
              `Skipping train with missing target: ${JSON.stringify(object)}`,
            );
            return;
          }
          const train = new Train(this, object);
          this.getTrainsForRoom(layer.roomId).push(train);
        }
      });
    });

    // Process diggable structures
    const diggableStructureLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.DIGGABLE_STRUCTURES}`),
    );

    diggableStructureLayers.forEach((layer) => {
      const objects = getTiledDiggableStructureObjectsFromMap(map, layer.name);
      objects.forEach((object) => {
        const structure = new DiggableStructure(this, object);
        this.getDiggableStructuresForRoom(layer.roomId).push(structure);
        this.diggableGroup.add(structure);
        this.structureGroup.add(structure);
      });
    });

    return map;
  }

  private onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix = camera.postFX.addColorMatrix();

      colorMatrix.saturate(0.1);
      colorMatrix.contrast(0.08);
      const matrix = colorMatrix.getData();
      matrix[0] *= 1.1;
      matrix[6] *= 1.03;
      matrix[12] *= 0.95;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xffaa66, 2, 0.3, false, 0.05, 6);
    }
  };

  protected override onRoundUpdate(): void {
    super.onRoundUpdate();
    this.updateMinesweeperHighlight();
    this.handleMinesweeperFlagInput();
  }

  protected override resetLevelObjects(): void {
    super.resetLevelObjects();
    // Reset minesweeper boards in the current room after death
    this.getMinesweepersForRoom(this.currentRoomId).forEach((minesweeper) => {
      minesweeper.resetObject();
    });
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);

    // Link barriers to trains in this room
    const trains = this.getTrainsForRoom(roomId);
    const roomObjects = this.rooms[roomId];
    if (!roomObjects) return;

    trains.forEach((train) => {
      // Find barriers with train triggers in this room
      const leftBarrier = roomObjects.animatedObjects.find(
        (obj) =>
          obj.texture.key === ASSET_KEYS.AUTO_BARRIER_LEFT &&
          (obj.trigger === "train_enter" || obj.trigger === "train_exit"),
      ) as AnimatedObject | undefined;

      const rightBarrier = roomObjects.animatedObjects.find(
        (obj) =>
          obj.texture.key === ASSET_KEYS.AUTO_BARRIER_RIGHT &&
          (obj.trigger === "train_enter" || obj.trigger === "train_exit"),
      ) as AnimatedObject | undefined;

      train.setBarriers(leftBarrier, rightBarrier);
    });

    this.getMinesweepersForRoom(roomId).forEach((minesweeper) => {
      minesweeper.enableObject();
    });
    this.getTrainsForRoom(roomId).forEach((train) => {
      train.enableObject();
    });
    this.getDiggableStructuresForRoom(roomId).forEach((structure) => {
      structure.enableObject();
    });
  }

  protected override disableRoomObjects(roomId: number): void {
    this.getMinesweepersForRoom(roomId).forEach((minesweeper) => {
      minesweeper.disableObject();
    });
    this.getTrainsForRoom(roomId).forEach((train) => {
      train.disableObject();
    });
    this.getDiggableStructuresForRoom(roomId).forEach((structure) => {
      structure.disableObject();
    });
    super.disableRoomObjects(roomId);
  }

  protected override appendRoomInteractiveObjects(
    roomId: number,
    objects: InteractiveGameObject[],
  ): void {
    super.appendRoomInteractiveObjects(roomId, objects);
  }

  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Register overlap for shovel tool with diggable structures and minesweepers
    const diggableGroup = this.diggableGroup;
    this.physics.add.overlap(
      this.playerObject.toolComponent.body,
      diggableGroup,
      (toolBody, target) => {
        const tool = this.playerObject.toolComponent.tool;
        if (!(tool instanceof Shovel) || !tool.inUse) {
          return;
        }

        const digTarget = tool.currentDigTarget;
        // Fallback to the tool body's center if shovel couldn't lock a dig target
        const toolPhysicsBody = toolBody as Phaser.Physics.Arcade.Body;
        const digWorldX =
          digTarget?.worldX ?? toolPhysicsBody.x + toolPhysicsBody.width / 2;
        const digWorldY =
          digTarget?.worldY ?? toolPhysicsBody.y + toolPhysicsBody.height / 2;

        // Handle diggable structures
        if (target instanceof DiggableStructure) {
          const destroyed = target.takeDamage(1);
          if (destroyed) {
            diggableGroup.remove(target, false, false);
            this.structureGroup.remove(target, false, false);
            this.refreshLevelObjects();
          }
          return;
        }

        // Handle minesweepers
        if (!(target instanceof Minesweeper)) {
          return;
        }

        if (!target.findGridSpace(digWorldX, digWorldY)) {
          return;
        }

        const isMine = target.dig(digWorldX, digWorldY);
        if (isMine) {
          this.playerObject.setDeathReason(DEATH_REASON.MINE_EXPLOSION_SELF);
          this.playerObject.hit(DIRECTION.DOWN, 1);
        }
        if (target.completed) {
          this.refreshLevelObjects();
          diggableGroup.remove(target, false, false);
          if (this.currentHighlightedMinesweeper === target) {
            target.hideHighlight();
            this.currentHighlightedMinesweeper = undefined;
          }
        }
      },
    );

    // Add collision detection for trains - kill player unless they're in boarding zone
    const allTrains = Array.from(this.trainsByRoom.values()).flat();

    this.physics.add.overlap(this.playerObject, allTrains, (player, train) => {
      const trainObj = train as Train;
      trainObj.checkPlayerCollision(
        this.playerObject,
        () => {
          // Player boards the train
          this.playerObject.setVisible(false);
          trainObj.boardPlayer(this.playerObject, () => {
            void this.#transportPlayerToDestination(trainObj);
          });
        },
        () => {
          // Player gets run over
          this.playerObject.setDeathReason(DEATH_REASON.TRAIN_RUN_OVER);
          this.playerObject.hit(DIRECTION.DOWN, 1);
        },
      );
    });
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();

    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
  }

  protected override applyRoundGameworldState(_currentLevel: string): void {
    super.applyRoundGameworldState(_currentLevel);
    this.minesweepersByRoom.forEach((minesweepers) => {
      minesweepers.forEach((minesweeper) => {
        minesweeper.initializeBoard();
      });
    });

    const keyTransferFlag = this.dataManager.getFlagValue(
      STORY_FLAG.dog_key_transfer,
    );
    if (keyTransferFlag === "completed") {
      this.dataManager.setFlagValue(STORY_FLAG.dog_key_pickup, "completed");
    }

    const roomtenRpFlag = this.dataManager.getFlagValue(STORY_FLAG.roomten_rp);
    this.diggableStructuresByRoom.forEach((structures) => {
      structures.forEach((structure) => {
        if (
          structure.storyFlag === STORY_FLAG.roomten_rock &&
          roomtenRpFlag === "completed"
        ) {
          structure.takeDamage(structure.hp);
        }
      });
    });
  }

  private getMinesweepersForRoom(roomId: number): Minesweeper[] {
    let list = this.minesweepersByRoom.get(roomId);
    if (!list) {
      list = [];
      this.minesweepersByRoom.set(roomId, list);
    }
    return list;
  }

  private getTrainsForRoom(roomId: number): Train[] {
    let list = this.trainsByRoom.get(roomId);
    if (!list) {
      list = [];
      this.trainsByRoom.set(roomId, list);
    }
    return list;
  }

  private getDiggableStructuresForRoom(roomId: number): DiggableStructure[] {
    let list = this.diggableStructuresByRoom.get(roomId);
    if (!list) {
      list = [];
      this.diggableStructuresByRoom.set(roomId, list);
    }
    return list;
  }

  async #transportPlayerToDestination(train: Train): Promise<void> {
    await this.transitionToRoom(
      train.getTargetRoomId(),
      train.getTargetDoorId(),
    );
    this.playerObject.setVisible(true);
  }

  private updateMinesweeperHighlight(): void {
    const tool = this.playerObject.toolComponent.tool;
    if (!(tool instanceof Shovel)) {
      if (this.currentHighlightedMinesweeper) {
        this.currentHighlightedMinesweeper.hideHighlight();
        this.currentHighlightedMinesweeper = undefined;
      }
      return;
    }

    const player = this.playerObject;
    const offset = Shovel.OFFSETS[player.direction];
    const toolX = player.x + offset.x + Shovel.SHOVEL_SIZE / 2;
    const toolY = player.y + offset.y + Shovel.SHOVEL_SIZE / 2;

    const minesweeper = this.findMinesweeperAt(toolX, toolY);
    if (minesweeper) {
      if (this.currentHighlightedMinesweeper !== minesweeper) {
        this.currentHighlightedMinesweeper?.hideHighlight();
        this.currentHighlightedMinesweeper = minesweeper;
      }
      minesweeper.showHighlight(toolX, toolY, COLOR_CLUE_FRAME_KEYS.DUG);
      return;
    }

    this.currentHighlightedMinesweeper?.hideHighlight();
    this.currentHighlightedMinesweeper = undefined;
  }

  private handleMinesweeperFlagInput(): void {
    if (!this.playerObject.controls.isFlagKeyJustDown) {
      return;
    }

    if (this.getMinesweepersForRoom(this.currentRoomId).length === 0) {
      return;
    }

    const player = this.playerObject;
    const offset = Shovel.OFFSETS[player.direction];
    const toolX = player.x + offset.x + Shovel.SHOVEL_SIZE / 2;
    const toolY = player.y + offset.y + Shovel.SHOVEL_SIZE / 2;
    const minesweeper = this.findMinesweeperAt(toolX, toolY);
    if (minesweeper) {
      minesweeper.toggleFlag(toolX, toolY);
      minesweeper.showHighlight(toolX, toolY, COLOR_CLUE_FRAME_KEYS.FLAG);
    }
  }

  private findMinesweeperAt(
    toolX: number,
    toolY: number,
  ): Minesweeper | undefined {
    return this.diggableGroup.getChildren().find((obj): obj is Minesweeper => {
      return obj instanceof Minesweeper && !!obj.findGridSpace(toolX, toolY);
    });
  }
}
