import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { TRAIN_FREQUENCY_MS } from "../../common/config";
import type { TiledVehicleObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import type { AnimatedObject } from "./animated-object";

export class Train
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  #isActive = false;
  #targetRoomId: number;
  #targetDoorId: number;
  #startX: number;
  #speed = 200; // pixels per second
  #timeEvent?: Phaser.Time.TimerEvent;
  #killZone: Phaser.GameObjects.Zone;
  #boardingZone: Phaser.GameObjects.Zone;
  #playerOnBoard?: Phaser.GameObjects.Sprite;
  #onArrivalCallback?: () => void;
  #leftBarrier?: AnimatedObject;
  #rightBarrier?: AnimatedObject;
  #whistleSound?: Phaser.Sound.BaseSound;

  constructor(scene: Phaser.Scene, vehicleData: TiledVehicleObject) {
    // Call super first - initialize the physics sprite
    super(scene, vehicleData.x, vehicleData.y, ASSET_KEYS.WESTERN_TRAIN);

    this.#targetRoomId = vehicleData.targetRoomId ?? 0;
    this.#targetDoorId = vehicleData.targetDoorId ?? 0;
    this.#startX = -this.width;

    scene.add.existing(this);
    scene.physics.add.existing(this);

    this.setOrigin(0, 0).setDepth(1.5).setImmovable(true).setVisible(false);

    // Set physics body to match sprite size (not Tiled object size)
    if (this.body) {
      this.body.setSize(this.width, this.height);
      this.body.enable = true;
    }

    // Create kill zone at the bottom half of the train (top half is safe)
    this.#killZone = scene.add.zone(
      vehicleData.x,
      vehicleData.y + this.height * 0.55, // lower 40% of train starting at 55% offset
      this.width,
      this.height * 0.4, // 40% of train height
    );
    this.#killZone.setOrigin(0, 0);
    scene.physics.add.existing(this.#killZone);

    this.#boardingZone = scene.add.zone(
      vehicleData.x,
      vehicleData.y + this.height * 0.5,
      160, // last two cars
      this.height * 0.5,
    );
    this.#boardingZone.setOrigin(0, 0);
    scene.physics.add.existing(this.#boardingZone);
  }

  enableObject(): void {
    this.#isActive = true;
    this.#scheduleNextAlignedRun();
  }

  disableObject(): void {
    this.#isActive = false;

    // Destroy any pending timers
    if (this.#timeEvent) {
      this.#timeEvent.destroy();
      this.#timeEvent = undefined;
    }

    // Stop any active tweens
    this.scene.tweens.killTweensOf(this);

    // Make the train invisible
    this.setVisible(false);

    // Reset position to start
    this.setX(this.#startX);

    // Clear any player on board
    this.#playerOnBoard = undefined;
    this.#onArrivalCallback = undefined;
  }

  #scheduleNextAlignedRun(): void {
    if (!this.#isActive) return;

    const now = Date.now();
    const msIntoMinute = now % TRAIN_FREQUENCY_MS;
    const delay = TRAIN_FREQUENCY_MS - msIntoMinute;

    this.#timeEvent = this.scene.time.addEvent({
      delay,
      callback: () => {
        if (!this.#isActive) return;
        this.#runTrain();
        // Schedule again for the next minute boundary
        this.#scheduleNextAlignedRun();
      },
    });
  }

  #getEndX(): number {
    return this.scene.cameras.main.width + this.width; // Off-screen right
  }

  #isTrackInView(): boolean {
    const camera = this.scene.cameras.main;
    const view = camera.worldView;
    const trackTop = this.y;
    const trackBottom = this.y + this.height;
    const buffer = 16; // small tolerance so borderline cases still count

    return trackBottom >= view.top - buffer && trackTop <= view.bottom + buffer;
  }

  public isPlayerOnBoard(player: Phaser.GameObjects.Sprite): boolean {
    return this.#playerOnBoard === player;
  }

  public boardPlayer(
    player: Phaser.GameObjects.Sprite,
    onArrival: () => void,
  ): void {
    this.#playerOnBoard = player;
    this.#onArrivalCallback = onArrival;
  }

  public checkPlayerCollision(
    player: Phaser.GameObjects.Sprite,
    onBoard: () => void,
    onKilled: () => void,
  ): void {
    if (!this.visible || this.isPlayerOnBoard(player)) {
      return;
    }

    const isInBoardingZone = this.scene.physics.overlap(
      player,
      this.#boardingZone,
    );

    if (isInBoardingZone) {
      onBoard();
      return;
    }

    const isInKillZone = this.scene.physics.overlap(player, this.#killZone);
    if (isInKillZone) {
      onKilled();
    }
  }

  public setBarriers(
    leftBarrier?: AnimatedObject,
    rightBarrier?: AnimatedObject,
  ): void {
    this.#leftBarrier = leftBarrier;
    this.#rightBarrier = rightBarrier;
  }

  public getTargetRoomId(): number {
    return this.#targetRoomId;
  }

  public getTargetDoorId(): number {
    return this.#targetDoorId;
  }

  #runTrain(): void {
    // Animate train from start to end position
    const endX = this.#getEndX();
    const distance = endX - this.#startX;
    const duration = (distance / this.#speed) * 1000;

    // Train spawns after a delay
    const trainSpawnDelay = 1500;
    // Open left barrier 500ms before train spawns
    const leftBarrierOpenDelay = trainSpawnDelay - 1200;

    // Open left barrier (train_enter trigger)
    if (this.#leftBarrier && this.#leftBarrier.trigger === "train_enter") {
      this.scene.time.delayedCall(leftBarrierOpenDelay, () => {
        this.#leftBarrier?.playAnimation("auto_barrier_left_open", () => {
          // Close barrier 1 second after opening completes
          this.scene.time.delayedCall(2000, () => {
            this.#leftBarrier?.playAnimation("auto_barrier_left_closed");
          });
        });
      });
    }

    // Start train movement after left barrier has time to open
    this.scene.time.delayedCall(trainSpawnDelay, () => {
      this.setVisible(true);
      this.setX(this.#startX);

      if (this.#isTrackInView()) {
        // Only play sound if window is focused to prevent queuing when window is unfocused
        if (document.hasFocus()) {
          // Stop any existing whistle sound before playing a new one
          if (this.#whistleSound && this.#whistleSound.isPlaying) {
            this.#whistleSound.stop();
          }
          const soundResult = this.scene.sound.play(
            ASSET_KEYS.TRAIN_WHISTLE_SFX,
          );
          // sound.play() can return BaseSound or boolean, check if it's a sound object
          if (soundResult && typeof soundResult === "object") {
            this.#whistleSound = soundResult as Phaser.Sound.BaseSound;
          }
        }
      }

      // Open right barrier 3 seconds after train starts moving (train_exit trigger)
      if (this.#rightBarrier && this.#rightBarrier.trigger === "train_exit") {
        this.scene.time.delayedCall(2500, () => {
          this.#rightBarrier?.playAnimation("auto_barrier_right_open", () => {
            // Close barrier 1 second after opening completes
            this.scene.time.delayedCall(2000, () => {
              this.#rightBarrier?.playAnimation("auto_barrier_right_closed");
            });
          });
        });
      }

      this.scene.tweens.add({
        targets: this,
        x: endX,
        duration,
        ease: "Linear",
        onUpdate: () => {
          // Manually sync body position with sprite during tween
          if (this.body) {
            this.body.updateFromGameObject();
          }
          // Also sync kill zone position
          this.#killZone.x = this.x;
          this.#killZone.y = this.y + this.height * 0.55;
          this.#boardingZone.x = this.x;
          this.#boardingZone.y = this.y + this.height * 0.5;

          // If player is on board, move them with the train
          if (this.#playerOnBoard) {
            this.#playerOnBoard.x =
              this.#boardingZone.x + this.#boardingZone.width / 2;
            this.#playerOnBoard.y =
              this.#boardingZone.y - this.#boardingZone.height / 2;
          }
        },
        onComplete: () => {
          this.setVisible(false);

          // If player is onboard, trigger arrival callback
          if (this.#playerOnBoard && this.#onArrivalCallback) {
            this.#onArrivalCallback();
            this.#playerOnBoard = undefined;
          }
        },
      });
    });
  }
}
