import * as Phaser from "phaser";
import { ASSET_KEYS, COLOR_CLUE_FRAME_KEYS } from "../../common/assets";
import { REVEAL_TRIGGER } from "../../common/tiled/constants";
import type {
  TiledColorClueObject,
  RevealTriggerType,
} from "../../common/tiled/types";
import type { CustomObject, CharacterColor } from "../../common/types";
import { DiggableComponent } from "../../components/diggable-component";
import { VisibilityComponent } from "../../components/visibility-component";
import type { MinesweeperInjectionType } from "../../entities/dynamic-injections/minesweeper";

export class ColorClue
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #frameKey: string;
  #visibleTo: CharacterColor[];
  #diggableComponent?: DiggableComponent;
  #number: number;

  constructor(scene: Phaser.Scene, config: TiledColorClueObject) {
    const frameKey = ColorClue.getFrameKey(
      config.number,
      config.revealClueTrigger,
      config.minesweeperInjectionType,
      config.x,
      config.y,
    );

    super(scene, config.x, config.y, ASSET_KEYS.COLOR_CLUES, frameKey);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0);

    this.#frameKey = frameKey;
    this.#visibleTo = config.visibleTo;
    this.#number = config.number;

    // Add components
    new VisibilityComponent(this, this.#visibleTo, false);
    if (config.revealClueTrigger === REVEAL_TRIGGER.DIG) {
      this.#diggableComponent = new DiggableComponent(this);
    }

    this.disableObject();
  }

  // Convert a number and trap type to the appropriate frame key
  static getFrameKey(
    number: number,
    trapType: RevealTriggerType,
    minesweeperInjectionType: MinesweeperInjectionType,
    x: number,
    y: number,
  ): string {
    // For DIG trap type, use number-based clues
    if (trapType === REVEAL_TRIGGER.DIG) {
      if (minesweeperInjectionType === "MINESWEEPER_BILLIARDS") {
        switch (number) {
          case 1:
            return COLOR_CLUE_FRAME_KEYS.YELLOW_BALL;
          case 2:
            return COLOR_CLUE_FRAME_KEYS.BLUE_BALL;
          case 3:
            return COLOR_CLUE_FRAME_KEYS.RED_BALL;
          case 4:
            return COLOR_CLUE_FRAME_KEYS.PURPLE_BALL;
          case 5:
            return COLOR_CLUE_FRAME_KEYS.ORANGE_BALL;
          case 6:
            return COLOR_CLUE_FRAME_KEYS.GREEN_BALL;
          case 7:
            return COLOR_CLUE_FRAME_KEYS.BROWN_BALL;
          case 8:
            return COLOR_CLUE_FRAME_KEYS.BLACK_BALL;
          // TODO: Add a better default frame key.
          default:
            return COLOR_CLUE_FRAME_KEYS.HOLE;
        }
      }
      const seed = 8 * x + y;
      if (minesweeperInjectionType === "MINESWEEPER_POKEMON") {
        switch (number) {
          case 1: {
            if (seed % 3 === 0) {
              return COLOR_CLUE_FRAME_KEYS.YELLOW_YANG;
            } else if (seed % 3 === 1) {
              return COLOR_CLUE_FRAME_KEYS.BLUE_YANG;
            } else {
              return COLOR_CLUE_FRAME_KEYS.RED_YANG;
            }
          }
          case 2: {
            if (seed % 2 === 0) {
              return COLOR_CLUE_FRAME_KEYS.SILVER_BAR;
            } else {
              return COLOR_CLUE_FRAME_KEYS.GOLD_BAR;
            }
          }
          case 3: {
            if (seed % 3 === 0) {
              return COLOR_CLUE_FRAME_KEYS.RUBY;
            } else if (seed % 3 === 1) {
              return COLOR_CLUE_FRAME_KEYS.SAPPHIRE;
            } else {
              return COLOR_CLUE_FRAME_KEYS.EMERALD;
            }
          }
          case 4: {
            if (seed % 2 === 0) {
              return COLOR_CLUE_FRAME_KEYS.DIAMOND;
            } else {
              return COLOR_CLUE_FRAME_KEYS.PEARL;
            }
          }
          case 5: {
            if (seed % 2 === 0) {
              return COLOR_CLUE_FRAME_KEYS.BLACK_YANG;
            } else {
              return COLOR_CLUE_FRAME_KEYS.WHITE_YANG;
            }
          }
          default:
            return COLOR_CLUE_FRAME_KEYS.HOLE;
        }
      }
      // Default to standard frame keys for standard minesweeper.
      switch (number) {
        case 1:
          return COLOR_CLUE_FRAME_KEYS.BONE;
        case 2:
          return COLOR_CLUE_FRAME_KEYS.TOWEL;
        case 3:
          return COLOR_CLUE_FRAME_KEYS.FEATHER;
        case 4:
          return COLOR_CLUE_FRAME_KEYS.FLOUR_BAG;
        // TODO: Add a better default frame key.
        default:
          return COLOR_CLUE_FRAME_KEYS.HOLE;
      }
    }

    // Default fallback for NONE or unknown trap types
    switch (number) {
      case 0:
        return COLOR_CLUE_FRAME_KEYS.HOLE;
      case 1:
        return COLOR_CLUE_FRAME_KEYS.MUSHROOM_ONE;
      case 2:
        return COLOR_CLUE_FRAME_KEYS.LOTUS_TWO;
      case 3:
        return COLOR_CLUE_FRAME_KEYS.FLOWER_THREE;
      case 4:
        return COLOR_CLUE_FRAME_KEYS.LEAF_FOUR;
      case 100:
        return COLOR_CLUE_FRAME_KEYS.FLAG;
      default:
        return COLOR_CLUE_FRAME_KEYS.HOLE;
    }
  }

  public getFrameKey(): string {
    return this.#frameKey;
  }

  public enableObject(): void {
    if (this.#diggableComponent?.isBuried()) {
      return;
    }
    this.active = true;
    this.visible = true;
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
  }

  public respawnObject(): void {
    this.enableObject();
  }

  get frameKey(): string {
    return this.#frameKey;
  }

  public getNumber(): number {
    return this.#number;
  }
}
