import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class OldBarkTownPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.OLD_BARK_TOWN_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadOldBarkTownAssets();
  }

  public create(): void {
    super.create();
    this.#createOldBarkTownAnimations();
  }

  #loadOldBarkTownAssets(): void {
    // Load western level
    this.load.image(ASSET_KEYS.WESTERN_BACKGROUND, WESTERN_BACKGROUND);
    this.load.image(ASSET_KEYS.WESTERN_FOREGROUND, WESTERN_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.WESTERN_LEVEL, WESTERN_LEVEL);

    // Load NPC sprites
    this.load.aseprite(ASSET_KEYS.SPOT, SPOT_IMG, SPOT_JSON);
    this.load.aseprite(ASSET_KEYS.HOTDOG, HOTDOG_IMG, HOTDOG_JSON);
    this.load.aseprite(ASSET_KEYS.NAPDOG, NAPDOG_IMG, NAPDOG_JSON);
    this.load.aseprite(ASSET_KEYS.POODLE, POODLE_IMG, POODLE_JSON);
    this.load.aseprite(ASSET_KEYS.SHERIFF, SHERIFF_IMG, SHERIFF_JSON);
    this.load.aseprite(ASSET_KEYS.LION, LION_IMG, LION_JSON);
    this.load.aseprite(ASSET_KEYS.PENGCAT, PENGCAT_IMG, PENGCAT_JSON);

    // Load train aseprite
    this.load.aseprite(ASSET_KEYS.WESTERN_TRAIN, TRAIN_IMG, TRAIN_JSON);

    // Load animated objects
    this.load.aseprite(
      ASSET_KEYS.AUTO_BARRIER_LEFT,
      AUTO_BARRIER_LEFT_IMG,
      AUTO_BARRIER_LEFT_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.AUTO_BARRIER_RIGHT,
      AUTO_BARRIER_RIGHT_IMG,
      AUTO_BARRIER_RIGHT_JSON,
    );

    // Load atlases
    this.load.atlas(ASSET_KEYS.COLOR_CLUES, COLOR_CLUES_IMG, COLOR_CLUES_JSON);
    this.load.atlas(
      ASSET_KEYS.WESTERN_ASSETS,
      WESTERN_ASSETS_IMG,
      WESTERN_ASSETS_JSON,
    );
    this.load.atlas(ASSET_KEYS.JAIL_BARS, JAIL_BARS_IMG, JAIL_BARS_JSON);

    // Load sounds
    this.load.audio(ASSET_KEYS.BARK_SFX, BARK_SOUND);
    this.load.audio(ASSET_KEYS.BELL_SFX, BELL_SOUND);
    this.load.audio(ASSET_KEYS.MEOW_SFX, MEOW_SOUND);
    this.load.audio(ASSET_KEYS.TRAIN_WHISTLE_SFX, TRAIN_WHISTLE_SOUND);

    // Load minesweeper data
    // Minesweeper Standard
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_0, MINESWEEPER_STANDARD_0);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_1, MINESWEEPER_STANDARD_1);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_2, MINESWEEPER_STANDARD_2);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_3, MINESWEEPER_STANDARD_3);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_4, MINESWEEPER_STANDARD_4);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_5, MINESWEEPER_STANDARD_5);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_6, MINESWEEPER_STANDARD_6);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_7, MINESWEEPER_STANDARD_7);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_8, MINESWEEPER_STANDARD_8);
    this.load.json(ASSET_KEYS.MINESWEEPER_STANDARD_9, MINESWEEPER_STANDARD_9);

    // Minesweeper Pokemon
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_0, MINESWEEPER_POKEMON_0);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_1, MINESWEEPER_POKEMON_1);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_2, MINESWEEPER_POKEMON_2);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_3, MINESWEEPER_POKEMON_3);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_4, MINESWEEPER_POKEMON_4);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_5, MINESWEEPER_POKEMON_5);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_6, MINESWEEPER_POKEMON_6);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_7, MINESWEEPER_POKEMON_7);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_8, MINESWEEPER_POKEMON_8);
    this.load.json(ASSET_KEYS.MINESWEEPER_POKEMON_9, MINESWEEPER_POKEMON_9);

    // Minesweeper Billiards
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_0, MINESWEEPER_BILLIARDS_0);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_1, MINESWEEPER_BILLIARDS_1);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_2, MINESWEEPER_BILLIARDS_2);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_3, MINESWEEPER_BILLIARDS_3);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_4, MINESWEEPER_BILLIARDS_4);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_5, MINESWEEPER_BILLIARDS_5);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_6, MINESWEEPER_BILLIARDS_6);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_7, MINESWEEPER_BILLIARDS_7);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_8, MINESWEEPER_BILLIARDS_8);
    this.load.json(ASSET_KEYS.MINESWEEPER_BILLIARDS_9, MINESWEEPER_BILLIARDS_9);

    // Load zone-specific data
    this.load.json(ASSET_KEYS.EVENTS, WESTERN_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, WESTERN_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, WESTERN_READABLES);

    // Load cat posters
    this.load.image(ASSET_KEYS.CATPOSTER_ANDANTE, ANDANTE_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_APPLE, APPLE_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_KIRBY, KIRBY_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_LYCHEE, LYCHEE_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_MAPLE, MAPLE_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_MIAOMIAO, MIAOMIAO_POSTER_IMG);
    this.load.image(ASSET_KEYS.CATPOSTER_NAMI, NAMI_POSTER_IMG);

    // Load wanted poster atlas
    this.load.atlas(
      ASSET_KEYS.WANTED_POSTER,
      WANTED_POSTER_IMG,
      WANTED_POSTER_JSON,
    );
  }

  #createOldBarkTownAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.HOTDOG);
    this.anims.createFromAseprite(ASSET_KEYS.NAPDOG);
    this.anims.createFromAseprite(ASSET_KEYS.POODLE);
    this.anims.createFromAseprite(ASSET_KEYS.SHERIFF);
    this.anims.createFromAseprite(ASSET_KEYS.SPOT);
    this.anims.createFromAseprite(ASSET_KEYS.LION);
    this.anims.createFromAseprite(ASSET_KEYS.PENGCAT);
    this.anims.createFromAseprite(ASSET_KEYS.WESTERN_TRAIN);
    this.anims.createFromAseprite(ASSET_KEYS.AUTO_BARRIER_LEFT);
    this.anims.createFromAseprite(ASSET_KEYS.AUTO_BARRIER_RIGHT);
  }
}
